-- Compatible models are copied only from the individual Cat product pages.
insert into public.part_catalog
(brand,part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,image_url,specifications,compatible_models)
values
('Caterpillar','603-8538','Carrier Roller Group - Cantilever, 120mm Tread','Cat carrier roller group, cantilever mount, standard application, 120 mm tread diameter; designed for General Duty undercarriage. Cat lists 320, 326 GC, 321, 320D3 GC, 320 GX, 323 GX, 333 GC, 324, 320D3, 322, 320 GX and 319 excavator models.',ARRAY[]::text[],'Undercarriage','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/603-8538','Official Cat product page lists EXCAVATOR models 320, 326 GC, 321, 320D3 GC, 320 GX, 323 GX, 333 GC, 324, 320D3, 322, 320 GX, 319 and 320 GC. Verify serial number and undercarriage configuration.','REFERENCE','https://caterpillar.scene7.com/is/image/Caterpillar/CM20231006-f1f7c-ab02b?fmt=WebP&hei=960&wid=960','{"shaft_mounting_length_in":2.736,"application":"Standard Application","uc_system":"GD","uc_system_designed_for":"General Duty","outside_spread_in":6.772,"inside_spread_in":1.929,"mount_type":"Cantilever","shaft_od_in":1.85,"flange_od_in":5.512,"tread_od_in":4.724}'::jsonb,ARRAY['320','326 GC','321','320D3 GC','320 GX','323 GX','333 GC','324','320D3','322','319','320 GC']::text[]),
('Caterpillar','235-5974','Carrier Roller Group - Cantilever, 199.5mm Tread','Cat carrier roller group, cantilever mount, standard application, 199.5 mm tread diameter; SystemOne track and Heavy Duty undercarriage. Cat lists D6-family track-type tractors, PL72 pipelayer and 963/973 track loaders.',ARRAY[]::text[],'Undercarriage','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/235-5974','Official Cat product page lists TRACK-TYPE TRACTOR D6R, D6T, D6R LGP, D6R II, D6T XW, D6T LGP, D6T LGPPAT, D6GC, D6T XL PAT, D6T XW PAT, D6 XE, D6R III, D6R XL, D6T XL, D6R STD, D6XE and D6; PIPELAYER PL72; TRACK LOADER 963D, 973D, 963C and 963K. Verify serial number and configuration.','REFERENCE','https://caterpillar.scene7.com/is/image/Caterpillar/CM20220428-17256-8acb5?fmt=WebP&hei=960&wid=960','{"outside_spread_in":8.031,"shaft_mounting_length_in":4.654,"application":"Standard Application","material":"Sealants / Adhesives Adhesive","uc_system":"HD","uc_system_designed_for":"Heavy Duty","inside_spread_in":2.146,"mount_type":"Cantilever","shaft_od_in":2.249,"flange_od_in":8.799,"tread_od_in":7.854}'::jsonb,ARRAY['D6R','D6T','D6R LGP','D6R II','D6T XW','D6T LGP','D6T LGPPAT','D6GC','D6T XL PAT','D6T XW PAT','D6 XE','D6R III','D6R XL','D6T XL','D6R STD','D6XE','D6','PL72','963D','973D','963C','963K']::text[]),
('Caterpillar','300-4545','Carrier Roller Group - Cantilever, 160mm Tread','Cat carrier roller group, cantilever mount, standard application, 160 mm tread diameter, Heavy Duty undercarriage. Cat lists 3512B Generator Set equipment as well as numerous excavator and mobile hydraulic power-unit configurations.',ARRAY['3512B']::text[],'Undercarriage','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/300-4545','Official Cat product page explicitly lists GENERATOR SET 3512B; it also lists numerous excavator, OEM and mobile hydraulic power-unit configurations. Only 3512B is recorded in engine_models here; confirm exact equipment serial number and arrangement.','REFERENCE','https://caterpillar.scene7.com/is/image/Caterpillar/CM20231006-5fdda-74269?fmt=WebP&hei=960&wid=960','{"shaft_mounting_length_in":2.945,"application":"Standard Application","uc_system":"HD","uc_system_designed_for":"Heavy Duty","outside_spread_in":7.638,"inside_spread_in":2.165,"mount_type":"Cantilever","shaft_od_in":1.874,"flange_od_in":7.402,"tread_od_in":6.299}'::jsonb,ARRAY['3512B','336MHPU','330F OEM','336E LN','340F','336 GC','336F','330D','329E','330C L','335F','336D','330F','349D L','349D2','345C L']::text[]),
('Caterpillar','542-8380','Carrier Roller Group - Cantilever, 190mm Tread','Cat carrier roller group, cantilever mount, standard application, 190 mm tread diameter, Heavy Duty undercarriage. Cat lists MD6380, MD6640, MD6540, 390F, 390F L, 395, MH3295, 374, 374F, 374F L and 3101.',ARRAY[]::text[],'Undercarriage','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/542-8380','Official Cat product page lists ROTARY DRILL MD6380; ROTARY/TRACK DRILLS MD6640 and MD6540; EXCAVATOR 390F, 390F L, 395, MH3295, 374, 374F, 374F L and 3101. Verify serial number and configuration.','REFERENCE','https://caterpillar.scene7.com/is/image/Caterpillar/CM20231006-a2b96-762c8?fmt=WebP&hei=960&wid=960','{"shaft_mounting_length_in":5.276,"application":"Standard Application","uc_system":"HD","uc_system_designed_for":"Heavy Duty","outside_spread_in":10.433,"inside_spread_in":3.386,"mount_type":"Cantilever","shaft_od_in":3.068,"flange_od_in":8.819,"tread_od_in":7.48}'::jsonb,ARRAY['MD6380','MD6640','MD6540','390F','390F L','395','MH3295','374','374F','374F L','3101']::text[])
